"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["93711"],{14648(e){e.exports=JSON.parse('{"id":"FIN-651","slug":"operating-cycle","term":"Operating Cycle","also_known_as":[],"difficulty":"Intermediate","definition":"The operating cycle is the average time it takes a business to buy inventory, sell it and collect the cash from customers.","explanation":["For many businesses, cash is tied up from the moment they buy stock until customers pay for the finished goods. The operating cycle measures that period.","It is calculated by adding days inventory outstanding, the average number of days inventory is held before being sold, and days sales outstanding, the average number of days it takes to collect payment from customers.","For example, if a company holds inventory for an average of 73 days and takes 73 days to collect from customers, its operating cycle is 146 days. Cash spent on stock is not recovered for nearly five months on average.","A shorter operating cycle means cash is tied up for less time, so the business needs less working capital to operate. Businesses can shorten the cycle by holding less inventory, speeding up production and collecting from customers faster.","The operating cycle does not consider how long the business takes to pay its own suppliers. Subtracting days payable outstanding gives the cash conversion cycle, which shows how long the business\'s own cash is tied up."],"note":"","total":1500,"prev":{"slug":"operating-cash-flow","term":"Operating Cash Flow"},"next":{"slug":"operating-expense","term":"Operating Expense"}}')}}]);